									<p class="text-xs text-amber-800/90 dark:text-amber-200/90">
										{{ $t('cart.installmentMobileWarningDesc') }}
									</p>
								</div>
							</div>

							<!-- Warning -->
							<div
								class="flex items-start bg-amber-500/10 border border-amber-500/20 text-amber-900 dark:text-amber-200 rounded-xl p-3 text-xs font-medium leading-5">
								<svg class="shrink-0 w-4 h-4 me-1 text-amber-600 dark:text-amber-400 mt-0.5" viewBox="0 0 24 24" fill="none"
									xmlns="http://www.w3.org/2000/svg">
									<path fill-rule="evenodd" clip-rule="evenodd"
										d="m3.517 17 7.058-11.783a1.667 1.667 0 0 1 2.85 0L20.483 17a1.667 1.667 0 0 1-1.425 2.5H4.942A1.666 1.666 0 0 1 3.517 17ZM12 9a1 1 0 0 1 1 1v3a1 1 0 1 1-2 0v-3a1 1 0 0 1 1-1Zm-1 7a1 1 0 0 1 1-1h.008a1 1 0 1 1 0 2H12a1 1 0 0 1-1-1Z"
										fill="currentColor"></path>
								</svg>
								<p>
									{{ $t('cart.warningBefore') }} <b class="font-semibold">{{ $t('cart.warningHour') }}</b>
									{{ $t('cart.warningMiddle') }}
									<router-link :to="{ name: 'panel-financial' }"
										class="font-semibold underline underline-offset-2">{{ $t('cart.warningLink') }}</router-link> {{ $t('cart.warningAfter') }}
								</p>
							</div>
						</div>
					</div>

					<!-- Sticky Footer Buttons -->
					<div class="shrink-0 pt-3 pb-1 border-t border-gray-100 dark:border-gray-800 bg-white/95 dark:bg-gray-900/95 sticky bottom-0 z-10">
						<div class="flex items-center justify-end gap-2">
							<button @click="isOpenCheckoutModal = false" :disabled="paymentLoading"
								class="px-4 h-10 flex items-center justify-center rounded-xl bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200 hover:bg-gray-200 dark:hover:bg-gray-700 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-60">
								{{ $t('cart.back') }}
							</button>
							<button v-if="paymentLoading" disabled="disabled"
								class="group relative inline-flex h-10 items-center justify-center overflow-hidden rounded-xl bg-neutral-950 px-5 text-sm font-medium text-neutral-200 disabled:pointer-events-none disabled:opacity-50">
								<span>{{ $t('cart.pleaseWait') }}</span>
								<svg viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg"
									class="ms-1 h-4 w-4 animate-spin text-white">
									<path
										d="M1.90321 7.29677C1.90321 10.341 4.11041 12.4147 6.58893 12.8439C6.87255 12.893 7.06266 13.1627 7.01355 13.4464C6.96444 13.73 6.69471 13.9201 6.41109 13.871C3.49942 13.3668 0.86084 10.9127 0.86084 7.29677C0.860839 5.76009 1.55996 4.55245 2.37639 3.63377C2.96124 2.97568 3.63034 2.44135 4.16846 2.03202L2.53205 2.03202C2.25591 2.03202 2.03205 1.80816 2.03205 1.53202C2.03205 1.25588 2.25591 1.03202 2.53205 1.03202L5.53205 1.03202C5.80819 1.03202 6.03205 1.25588 6.03205 1.53202L6.03205 4.53202C6.03205 4.80816 5.80819 5.03202 5.53205 5.03202C5.25591 5.03202 5.03205 4.80816 5.03205 4.53202L5.03205 2.68645L5.03054 2.68759L5.03045 2.68766L5.03044 2.68767L5.03043 2.68767C4.45896 3.11868 3.76059 3.64538 3.15554 4.3262C2.44102 5.13021 1.90321 6.10154 1.90321 7.29677ZM13.0109 7.70321C13.0109 4.69115 10.8505 2.6296 8.40384 2.17029C8.12093 2.11718 7.93465 1.84479 7.98776 1.56188C8.04087 1.27898 8.31326 1.0927 8.59616 1.14581C11.4704 1.68541 14.0532 4.12605 14.0532 7.70321C14.0532 9.23988 13.3541 10.4475 12.5377 11.3662C11.9528 12.0243 11.2837 12.5586 10.7456 12.968L12.3821 12.968C12.6582 12.968 12.8821 13.1918 12.8821 13.468C12.8821 13.7441 12.6582 13.968 12.3821 13.968L9.38205 13.968C9.10591 13.968 8.88205 13.7441 8.88205 13.468L8.88205 10.468C8.88205 10.1918 9.10591 9.96796 9.38205 9.96796C9.65819 9.96796 9.88205 10.1918 9.88205 10.468L9.88205 12.3135L9.88362 12.3123C10.4551 11.8813 11.1535 11.3546 11.7585 10.6738C12.4731 9.86976 13.0109 8.89844 13.0109 7.70321Z"
										fill="currentColor" fill-rule="evenodd" clip-rule="evenodd"></path>
								</svg>
							</button>
							<button v-else @click="onCheckoutPay"
								:disabled="paymentMethod === 'wallet' && payableAmount > 0 && walletBalance <= 0"
								class="px-6 h-10 flex items-center justify-center rounded-xl bg-amber-500 hover:bg-amber-400 text-gray-950 text-sm font-bold shadow-sm shadow-amber-500/20 transition-all disabled:opacity-70 disabled:cursor-not-allowed">
								{{ payableAmount === 0 || (paymentMethod === 'wallet' && walletSufficient) ?
									$t('cart.confirmReceipt') : (paymentMethod === 'wallet' ? $t('cart.payWalletAndGateway') : $t('cart.confirmGateway')) }}
							</button>
						</div>
					</div>
			</div>
					<div v-else key="gateway" class="flex-1 overflow-y-auto space-y-4 px-1 pt-12 text-start custom-scrollbar">
						<p class="text-sm font-bold text-gray-900 dark:text-gray-100">{{ $t('cart.walletInsufficientTitle') }}</p>
						<p class="text-xs leading-6 text-gray-600 dark:text-gray-300">
							{{ $t('cart.walletInsufficientDesc', {
								wallet: walletBalance.toLocaleString(),
								remainder: walletSplitRemainder.toLocaleString(),
							}) }}
						</p>
						<div :class="paymentLoading ? 'pointer-events-none opacity-60' : ''">
							<p class="mb-2 text-xs font-semibold text-gray-700 dark:text-gray-200">{{ $t('cart.selectGateway') }}</p>
							<PaymentGatewayList v-model="walletSplitGateway" :gateways="directBankGateways" />
						</div>
						<button
							type="button"
							class="flex w-full items-center justify-center gap-2 rounded-xl bg-yellow-500 px-4 py-2.5 text-sm font-semibold text-black disabled:cursor-not-allowed disabled:opacity-70"
							:disabled="paymentLoading || !walletSplitGateway"
							@click="confirmWalletSplitPayment"
						>
							<svg v-if="paymentLoading" class="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none" aria-hidden="true">
								<circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
								<path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"></path>
							</svg>
							{{ $t('cart.walletInsufficientConfirm') }}
						</button>
					</div>
				</Transition>
			</div>
		</BottomSheetDrawer>

		<!-- Installment Cart Ineligible BottomSheet -->
		<BottomSheetDrawer v-model="isOpenInstallmentRestrictionModal" max-width-class="max-w-lg">
			<div class="px-2 py-3 text-start">
				<div class="flex items-center gap-2 mb-3">
					<div class="w-10 h-10 rounded-full bg-amber-100 dark:bg-amber-900/40 text-amber-600 dark:text-amber-400 flex items-center justify-center shrink-0">
						<svg class="w-6 h-6" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
							<path fill-rule="evenodd" clip-rule="evenodd"
								d="m3.517 17 7.058-11.783a1.667 1.667 0 0 1 2.85 0L20.483 17a1.667 1.667 0 0 1-1.425 2.5H4.942A1.666 1.666 0 0 1 3.517 17ZM12 9a1 1 0 0 1 1 1v3a1 1 0 1 1-2 0v-3a1 1 0 0 1 1-1Zm-1 7a1 1 0 0 1 1-1h.008a1 1 0 1 1 0 2H12a1 1 0 0 1-1-1Z"
								fill="currentColor"></path>
						</svg>
					</div>
					<div>
						<h3 class="text-base font-bold text-gray-900 dark:text-gray-100">
							{{ $t('cart.installmentRestrictionTitle') }}
						</h3>
						<p class="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
							{{ $t('cart.installmentRestrictionDesc') }}
						</p>
					</div>
				</div>

				<!-- Ineligible Items List -->
				<div class="my-4 space-y-2 max-h-56 overflow-y-auto px-1">
					<div
						v-for="item in nonInstallmentItemsInCart"
						:key="item.id"
						class="flex items-center justify-between p-2.5 rounded-xl border border-rose-200 dark:border-rose-900/60 bg-rose-50/50 dark:bg-rose-950/20 text-xs"
					>
						<div class="flex items-center gap-2 min-w-0">
							<span class="px-2 py-0.5 rounded text-[10px] font-semibold bg-rose-100 dark:bg-rose-900/60 text-rose-700 dark:text-rose-300 shrink-0">
								{{ $t('cart.installmentIneligibleBadge') }}
							</span>
							<span class="truncate font-medium text-gray-800 dark:text-gray-200">
								{{ getCartItemTitle(item, $t) }}
							</span>
						</div>
						<button
							type="button"
							@click="removeSingleNonInstallmentItem(item.id)"
							class="text-rose-600 hover:text-rose-800 dark:text-rose-400 p-1 rounded-lg hover:bg-rose-100/50 dark:hover:bg-rose-900/40 shrink-0 transition-colors"
						>
							<svg class="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
								<path stroke-linecap="round" stroke-linejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
							</svg>
						</button>
					</div>
				</div>

				<!-- Actions -->
				<div class="flex flex-col sm:flex-row gap-2 mt-5">
					<button
						type="button"
						@click="removeNonInstallmentItemsAndProceed"
						:disabled="removingNonInstallmentItems"
						class="flex-1 py-2.5 px-4 rounded-xl text-xs font-bold bg-amber-500 hover:bg-amber-600 text-black flex items-center justify-center gap-1.5 transition-all disabled:opacity-60"
					>
						<svg v-if="removingNonInstallmentItems" class="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none">
							<circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
							<path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"></path>
						</svg>
						<span>{{ removingNonInstallmentItems ? $t('cart.installmentRemoving') : $t('cart.installmentRemoveIneligibleAndProceed') }}</span>
					</button>
					<button
						type="button"
						@click="switchToDirectBankGateway"
						class="flex-1 py-2.5 px-4 rounded-xl text-xs font-bold bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 text-gray-800 dark:text-gray-100 transition-all text-center"
					>
						{{ $t('cart.installmentPayWithOtherGateways') }}
					</button>
				</div>
			</div>
		</BottomSheetDrawer>



	</MasterPage>
</template>
<script setup>
import { useAuthStore } from '@/stores/auth'
import { useCartStore } from '@/stores/cart'
const authStore = useAuthStore()
const cartStore = useCartStore()
import MasterPage from "@/views/page/layouts/MasterPage.vue";
import BottomSheetDrawer from "@/views/components/common/BottomSheetDrawer.vue";
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRouter } from "vue-router";
import axiosInstance from "@/store/axiosInstance";
import { toast } from "vue3-toastify";
import "vue3-toastify/dist/index.css";
import { useI18n } from "vue-i18n";
import PaymentGatewayList from "@/views/components/payment/PaymentGatewayList.vue";
import CartAnimatedPrice from "@/views/components/cart/CartAnimatedPrice.vue";
import DiscountBreakdown from "@/views/components/cart/DiscountBreakdown.vue";
import GatewayFeeHelp from "@/views/components/cart/GatewayFeeHelp.vue";
import SeoImage from "@/views/components/seo/SeoImage.vue";
import tomanIcon from "@/assets/image/svg/Toman.svg";
import {
	buildPaymentGateways,
	calculateCartGatewayPricing,
	cartHasInstallmentEligibleItems,
	filterDirectBankGateways,
	filterGatewaysForCart,
	findGatewayById,
	getCartItemBasePrice,
	getCartItemTitle,
	getDefaultGateway,
	gatewayPayPayload,
	isDigipayFeeGateway,
	isInstallmentGateway,
	isCartFullyInstallmentEligible,
	getNonInstallmentCartItems,
	isCartItemInstallmentEligible,
	fetchGatewayCommissions,
} from "@/config/paymentGateways";
const { t } = useI18n();
const router = useRouter();

const hiddenItems = ref([]);
const pendingDeletes = ref([]);
const paymentMethod = ref('bank');
const selectedGateway = ref(null);
const showPriceUpdatedToast = ref(false);
const checkoutStep = ref('invoice');
const walletSplitRemainder = ref(0);
const walletSplitGateway = ref(null);
const paymentLoading = ref(false);
const isOpenInstallmentRestrictionModal = ref(false);
const removingNonInstallmentItems = ref(false);
let priceToastTimer = null;

const currentUser = computed(() => authStore.status.userInfo);
const cartItems = computed(() => cartStore.cartItems);
const visibleCartItems = computed(() => {
	return cartItems.value.filter(item => {
		return !hiddenItems.value.includes(item.id);
	});
});

const isCartFullyInstallment = computed(() => {
	return isCartFullyInstallmentEligible(visibleCartItems.value);
});

const nonInstallmentItemsInCart = computed(() => {
	return getNonInstallmentCartItems(visibleCartItems.value);
});

const isCurrentGatewayInstallment = computed(() => {
	return paymentMethod.value === 'bank' && isInstallmentGateway(selectedGateway.value);
});

const cartLoading = computed(() => cartStore.loading);
const totalCartPrice = computed(() => {
	return cartStore.totalCartPrice;
});
const totalDiscount = computed(() => {
	return cartStore.totalDiscount;
});
const totalOriginal = computed(() => cartStore.totalOriginal);
const totalCourseDiscount = computed(() => cartStore.totalCourseDiscount);
const totalCouponDiscount = computed(() => cartStore.totalCouponDiscount);
const appliedCoupon = computed(() => cartStore.appliedCoupon);
const discountCodeApplied = computed(() => cartStore.getDiscountCode);

const gateways = computed(() => buildPaymentGateways(t));
const availableGateways = computed(() => filterGatewaysForCart(gateways.value, visibleCartItems.value));
const directBankGateways = computed(() => filterDirectBankGateways(availableGateways.value));
const hasInstallmentEligible = computed(() => cartHasInstallmentEligibleItems(visibleCartItems.value));
const walletBalance = computed(() => Number(currentUser?.value?.wallet_balance || 0));

const cartPricing = computed(() => {
	const pricing = calculateCartGatewayPricing(
		visibleCartItems.value,
		selectedGateway.value,
		paymentMethod.value,
	);

	return {
		...pricing,
		items: pricing.items.map((row) => {
			const item = visibleCartItems.value.find((cartItem) => cartItem.id === row.id);

			return {
				...row,
				title: item ? getCartItemTitle(item, t) : '',
			};
		}),
	};
});

const showGatewayFee = computed(() => paymentMethod.value === 'bank' && cartPricing.value.hasFee);
const payableAmount = computed(() => Number(cartPricing.value.chargedTotal || 0));
const walletSufficient = computed(() => walletBalance.value >= payableAmount.value);
const walletSplitActive = computed(() => paymentMethod.value === 'wallet' && payableAmount.value > 0 && walletBalance.value > 0 && !walletSufficient.value);
const walletSplitAmount = computed(() => walletSplitActive.value ? Math.min(walletBalance.value, payableAmount.value) : 0);
const gatewaySplitAmount = computed(() => walletSplitActive.value ? Math.max(0, payableAmount.value - walletBalance.value) : 0);

function getItemPricing(item) {
	const priced = cartPricing.value.items.find((row) => row.id === item.id);

	if (priced) {
		return priced;
	}

	const basePrice = getCartItemBasePrice(item);

	return {
		basePrice,
		chargedPrice: basePrice,
		hasFee: false,
	};
}

onMounted(() => {
	document.title = t('cart.pageTitle');
	fetchGatewayCommissions();
	selectedGateway.value = getDefaultGateway(gateways.value);
});

watch(gateways, (list) => {
	const currentId = selectedGateway.value?.id;
	const resolved = currentId ? findGatewayById(list, currentId) : null;
	const next = resolved || getDefaultGateway(list);
	if (next?.id !== currentId) {
		selectedGateway.value = next;
	}
});

watch(availableGateways, (list) => {
	const currentId = selectedGateway.value?.id;
	if (!currentId) {
		return;
	}

	if (!list.some((gateway) => gateway.id === currentId)) {
		selectedGateway.value = getDefaultGateway(list);
	}
});

watch(selectedGateway, (gateway, previous) => {
	if (!gateway) {
		return;
	}

	if (isInstallmentGateway(gateway) && !hasInstallmentEligible.value) {
		toast.error(t('cart.noInstallmentEligible'), {
			theme: "colored",
			hideProgressBar: false,
			rtl: localStorage.getItem("direction") == "rtl",
			bodyClassName: "font-YekanBakh",
			toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
			position: toast.POSITION.BOTTOM_CENTER,
		});
		selectedGateway.value = previous || getDefaultGateway(availableGateways.value);
		return;
	}

	const wasDigipay = isDigipayFeeGateway(previous);
	const isDigipay = isDigipayFeeGateway(gateway);
	if (wasDigipay !== isDigipay) {
		showPriceUpdatedToast.value = true;
		clearTimeout(priceToastTimer);
		priceToastTimer = setTimeout(() => {
			showPriceUpdatedToast.value = false;
		}, 4000);
	}
});

watch(paymentMethod, (method, previousMethod) => {
	if (!previousMethod || method === previousMethod) {
		return;
	}

	if (isDigipayFeeGateway(selectedGateway.value)) {
		showPriceUpdatedToast.value = true;
		clearTimeout(priceToastTimer);
		priceToastTimer = setTimeout(() => {
			showPriceUpdatedToast.value = false;
		}, 4000);
	}
});

const now = ref(Date.now());
let nowTimer = null;

onMounted(() => {
	nowTimer = setInterval(() => {
		now.value = Date.now();
	}, 50);
});

onBeforeUnmount(() => {
	if (nowTimer) clearInterval(nowTimer);
});

const isOpenCheckoutModal = ref(false);
const shouldReopenCheckoutOnFeeClose = ref(false);
const sidebarFeeHelpRef = ref(null);

function onCheckoutFeeHelpBeforeOpen() {
	if (isOpenCheckoutModal.value) {
		shouldReopenCheckoutOnFeeClose.value = true;
		isOpenCheckoutModal.value = false;
	}

	nextTick(() => {
		sidebarFeeHelpRef.value?.open();
	});
}

function onSidebarFeeHelpBeforeOpen() {
	shouldReopenCheckoutOnFeeClose.value = false;
}

function onFeeHelpClose() {
	if (!shouldReopenCheckoutOnFeeClose.value) {
		return;
	}

	shouldReopenCheckoutOnFeeClose.value = false;
	nextTick(() => {
		isOpenCheckoutModal.value = true;
	});
}

function openCheckoutSheet() {
	if (isCurrentGatewayInstallment.value && !isCartFullyInstallment.value) {
		isOpenInstallmentRestrictionModal.value = true;
		return;
	}
	checkoutStep.value = 'invoice';
	isOpenCheckoutModal.value = true;
}

function onCheckoutPay() {
	if (isCurrentGatewayInstallment.value && !isCartFullyInstallment.value) {
		isOpenCheckoutModal.value = false;
		isOpenInstallmentRestrictionModal.value = true;
		return;
	}

	if (paymentMethod.value === 'wallet' && payableAmount.value > 0 && walletBalance.value > 0 && !walletSufficient.value) {
		walletSplitRemainder.value = payableAmount.value - walletBalance.value;
		walletSplitGateway.value = getDefaultGateway(directBankGateways.value);
		checkoutStep.value = 'gateway';
		isOpenCheckoutModal.value = true;
		return;
	}

	sendPaymentRequest();
}

async function removeNonInstallmentItemsAndProceed() {
	if (removingNonInstallmentItems.value) return;
	removingNonInstallmentItems.value = true;
	try {
		const ineligible = [...nonInstallmentItemsInCart.value];
		for (const item of ineligible) {
			hiddenItems.value.push(item.id);
		}
		await Promise.all(ineligible.map(item => cartStore.removeFromCart(item.id)));
		isOpenInstallmentRestrictionModal.value = false;
		checkoutStep.value = 'invoice';
		isOpenCheckoutModal.value = true;
	} catch (error) {
		console.error("Error removing non-installment items:", error);
		toast.error(t('cart.toastRemoveError'));
		await cartStore.getCart();
	} finally {
		removingNonInstallmentItems.value = false;
	}
}

function switchToDirectBankGateway() {
	isOpenInstallmentRestrictionModal.value = false;
	const directGateway = getDefaultGateway(directBankGateways.value);
	if (directGateway) {
		selectedGateway.value = directGateway;
	}
	checkoutStep.value = 'invoice';
	isOpenCheckoutModal.value = true;
}

async function removeSingleNonInstallmentItem(itemId) {
	try {
		hiddenItems.value.push(itemId);
		await cartStore.removeFromCart(itemId);
		if (isCartFullyInstallment.value) {
			isOpenInstallmentRestrictionModal.value = false;
			checkoutStep.value = 'invoice';
			isOpenCheckoutModal.value = true;
		}
	} catch (error) {
		console.error("Error removing item:", error);
		toast.error(t('cart.toastRemoveError'));
		await cartStore.getCart();
	}
}

async function sendPaymentRequest(options = {}) {
	await flushPendingDeletes();
	paymentLoading.value = true;
	try {
		let payPayload = paymentMethod.value === 'bank'
			? { payment_method: 'bank', ...gatewayPayPayload(selectedGateway.value) }
			: { payment_method: 'wallet' };

		if (options.walletSplitConfirmed) {
			payPayload = {
				payment_method: 'wallet',
				wallet_split_confirmed: true,
				...gatewayPayPayload(walletSplitGateway.value || selectedGateway.value),
			};
		}

		await axiosInstance.post("/cart/pay", payPayload).then((response) => {
			const data = response?.data || {};
			const isPaid = data.status === 'paid';
			const isInternalRedirect = !!(isPaid || (typeof data.redirect_url === 'string' && data.redirect_url.includes('/payment/receipt/')));

			if (isInternalRedirect) {
				const uuidFromUrl = typeof data.redirect_url === 'string' ? data.redirect_url.split('/').pop() : null;
				const uuid = data.payment_uuid || uuidFromUrl;
				if (uuid) {
					router.push({ name: 'payment-receipt', params: { uuid } });
				} else {
					// Fallback: go to financial panel if uuid missing
					router.push({ name: 'panel-financial' });
				}
			} else if (data.redirect_url) {
				window.location.href = data.redirect_url;
				return;
			} else {
				paymentLoading.value = false;
				toast.error(t('cart.toastLinkError'), {
					theme: "colored",
					hideProgressBar: false,
					rtl: localStorage.getItem("direction") == "rtl" ? true : false,
					bodyClassName: "font-YekanBakh",
					toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
					transition: toast.TRANSITIONS.BOUNCE,
					position: toast.POSITION.BOTTOM_RIGHT,
				});
			}
		});
	} catch (error) {
		paymentLoading.value = false;
		if (error?.response?.status !== 422) {
			console.error("An error occurred:", error);
		}

		if (error?.response?.data?.code === 'wallet_insufficient') {
			walletSplitRemainder.value = Number(error.response.data.gateway_remainder || 0);
			walletSplitGateway.value = getDefaultGateway(directBankGateways.value);
			checkoutStep.value = 'gateway';
			isOpenCheckoutModal.value = true;
			return;
		}

		toast.error(error?.response?.data?.error || t('cart.toastPayError'), {
			theme: "colored",
			hideProgressBar: false,
			rtl: localStorage.getItem("direction") == "rtl" ? true : false,
			bodyClassName: "font-YekanBakh",
			toastClassName: "rounded-xl text-sm font-semibold mb-4 mx-3 md:mx-0",
			transition: toast.TRANSITIONS.BOUNCE,
			position: toast.POSITION.BOTTOM_RIGHT,
		});
	}
}

async function confirmWalletSplitPayment() {
	if (paymentLoading.value) return;
	await sendPaymentRequest({ walletSplitConfirmed: true });
}


const discountCode = ref('');

const discountLoading = ref(false);

watch(appliedCoupon, (coupon) => {
	if (coupon?.code) {
		discountCode.value = coupon.code;
	}
}, { immediate: true });


const applyDiscount = async () => {
	if (!discountCode.value.trim()) {
		return;
	}

	discountLoading.value = true;

	try {
		await cartStore.applyDiscountCode(discountCode.value);
		discountLoading.value = false;
	} catch (error) {
		discountLoading.value = false;
		console.error("Error in apply discount:", error);
	}
};

const removeDiscount = async () => {
	discountLoading.value = true;

	try {
		await cartStore.removeDiscountCode();
		discountLoading.value = false;
		discountCode.value = "";
	} catch (error) {
		discountLoading.value = false;
		console.error("Error in remove discount:", error);
	}
};

const getPendingDelete = (id) => {

	return pendingDeletes.value.find(
		item => item.id === id
	);

};

const scheduleRemoveFromCart = (item) => {

	if (getPendingDelete(item.id))
		return;

	hiddenItems.value.push(item.id);

	const timeoutId = setTimeout(() => {

		finalizeDelete(item.id);

	}, 5000);

	pendingDeletes.value.push({
		id: item.id,
		title: item.title,
		timeoutId,
		startedAt: Date.now()
	});

};

const undoDelete = (id) => {

	const item = getPendingDelete(id);

	if (!item)
		return;

	clearTimeout(item.timeoutId);

	hiddenItems.value =
		hiddenItems.value.filter(
			x => x !== id
		);

	pendingDeletes.value =
		pendingDeletes.value.filter(
			x => x.id !== id
		);

};

const finalizeDelete = (id) => {

	pendingDeletes.value =
		pendingDeletes.value.filter(
			x => x.id !== id
		);

	cartStore.removeFromCart(id
	).catch(error => {

		console.error(error);

		hiddenItems.value =
			hiddenItems.value.filter(
				x => x !== id
			);

		cartStore.getCart();

		toast.error(t('cart.toastRemoveError'));

	});

};

const flushPendingDeletes = async () => {

	const requests = [...pendingDeletes.value];

	pendingDeletes.value = [];

	await Promise.all(

		requests.map(item => {

			clearTimeout(item.timeoutId);

			return cartStore.removeFromCart(item.id
			);

		})

	);

};

const getRemainingSeconds = (id) => {

	const item = getPendingDelete(id);

	if (!item)
		return 0;

	const elapsed =
		now.value - item.startedAt;

	return Math.max(
		0,
		Math.ceil((5000 - elapsed) / 1000)
	);

};

const getRemainingPercent = (id) => {

	const item = getPendingDelete(id);

	if (!item)
		return 0;

	const elapsed =
		now.value - item.startedAt;

	return Math.max(
		0,
		100 - (elapsed / 5000) * 100
	);

};



</script>

